import { MeshBasicNodeMaterial, PlaneGeometry, DoubleSide } from 'three/webgpu';
import { vec4, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, Vector3 } = ctx.THREE;

  // Create the main container group
  const group = new Group();

  // Setup layout variables from visual specifications
  const palette = config.intent?.visualSpec?.colors ?? {
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    surface: "#0b0b10"
  };

  const badgeWidth = 1.6;
  const badgeHeight = 0.5;
  const geometry = new PlaneGeometry(badgeWidth, badgeHeight);

  // Custom Node Material demonstrating the capsule edge glowing effect with TSL
  const material = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true
  });

  // TSL implementation for the capsule with an accent edge light mapping
  material.colorNode = vec4(ctx.THREE.Color.getCurrentColor ?? (() => {
    // Fallback/standard procedural coloring
    const colInk = color(palette.surface);
    const colAccent = color(palette.accent);
    return vec4(colInk.rgb, 1.0);
  })());

  // Alternate direct design implementation to guarantee visually rich capsule aesthetic
  const inkColor = new ctx.THREE.Color(palette.surface);
  const accentColor = new ctx.THREE.Color(palette.accent);
  const paperColor = new ctx.THREE.Color(palette.paper);

  material.color.copy(inkColor);

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Optional capsule background border / edge glow
  const borderGeo = new PlaneGeometry(badgeWidth * 1.05, badgeHeight * 1.15);
  const borderMat = new MeshBasicNodeMaterial({
    color: accentColor,
    side: DoubleSide,
    transparent: true,
    opacity: 0.85
  });
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.z = -0.01;
  group.add(borderMesh);

  // Load the texture if provided in high-quality style
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      material.map = texture;
      material.needsUpdate = true;
    }).catch(() => {});
  }

  // Create the text element for the pricing badge (usually "PRICING" or "ATELIER ACCESS")
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textLabel = items.length > 0 ? items[0].text : "PRICING";

  const textMesh = ctx.fontAtlas.createText(textLabel, {
    fontSize: 11,
    color: palette.paper,
    align: 'center'
  });
  textMesh.position.set(0, -0.03, 0.02);
  group.add(textMesh);

  // Apply visual transitions or positions configured
  // Notice: The adapter positions the root node, but we configure internal structure responses
  group.position.set(0, 0, 0);

  // Keep references to timelines for proper cleanup
  const activeTimelines = [];

  // Interaction handlers stored in userData
  const handlers = {
    pointerenter: () => {
      const tl = gsap.timeline();
      tl.to(group.position, {
        y: 0.15,
        duration: 0.3,
        ease: 'power3.out'
      });
      tl.to(borderMat, {
        opacity: 1.0,
        duration: 0.2
      }, 0);
      activeTimelines.push(tl);
    },
    pointerleave: () => {
      const tl = gsap.timeline();
      tl.to(group.position, {
        y: 0,
        duration: 0.4,
        ease: 'power2.out'
      });
      tl.to(borderMat, {
        opacity: 0.85,
        duration: 0.3
      }, 0);
      activeTimelines.push(tl);
    },
    click: () => {
      const tl = gsap.timeline();
      tl.to(group.scale, {
        x: 0.93,
        y: 0.93,
        duration: 0.1,
        yoyo: true,
        repeat: 1,
        ease: 'power2.inOut'
      });
      activeTimelines.push(tl);

      // Emit event as specified in mapping behavior
      ctx.emit('hub-pricing.select', { id: config.id ?? 'pricing-badge' });
    }
  };

  group.userData = {
    handlers,
    cleanup: () => {
      activeTimelines.forEach(tl => tl.kill());
      geometry.dispose();
      material.dispose();
      borderGeo.dispose();
      borderMat.dispose();
    }
  };

  return group;
}
